if.script:
boolean _dz = ec.artifactExecution.disableAuthz()
context._twoFaActive = false
try {
    def _ua = _preU ? ec.entity.find("moqui.security.UserAccount").condition("username", _preU).one() : null
    if (_ua?.userId) context._twoFaActive = ec.entity.find("moqui.security.UserAuthcFactor")
            .condition("userId", _ua.userId).condition("needsValidation", "N")
            .conditionDate("fromDate", "thruDate", ec.user.nowTimestamp).count() > 0
} finally { if (!_dz) ec.artifactExecution.enableAuthz() }

ec.web.sessionAttributes.remove('zenithRememberMe')
ec.web.sessionAttributes.remove('zenithLoginOrgId')
ec.message.clearAll()
ec.message.addError("The username or password you entered is incorrect.")
// ZE-ROLE-002: if the credentials are actually correct but the account is DISABLED, tell
// the user clearly instead of the misleading generic message. We verify the password
// first so this never becomes a username-enumeration oracle — only someone who knows the
// account's password (the legitimate owner) ever sees the "disabled" message.
boolean _dz = ec.artifactExecution.disableAuthz()
try {
    def ua = username ? ec.entity.find("moqui.security.UserAccount").condition("username", username).one() : null
    if (ua?.disabled == "Y" && ua.currentPassword && password) {
        def token = new org.apache.shiro.authc.UsernamePasswordToken((String) ua.username, (String) password)
        def info = new org.apache.shiro.authc.SimpleAuthenticationInfo((String) ua.username, (String) ua.currentPassword,
                new org.apache.shiro.lang.util.SimpleByteSource((String) (ua.passwordSalt ?: "")), "moquiRealm")
        if (ec.ecfi.getCredentialsMatcher(ua.passwordHashType, "Y".equals(ua.passwordBase64)).doCredentialsMatch(token, info)) {
            ec.message.clearAll()
            ec.message.addError("Your account has been disabled. Please contact your administrator.")
        }
    }
} finally { if (!_dz) ec.artifactExecution.enableAuthz() }

boolean adDis = ec.artifactExecution.disableAuthz()
try {
    def ev = ec.entity.find("moqui.security.UserPreference")
        .condition("userId", ec.user.userId).condition("preferenceKey", "EMAIL_VERIFIED").one()
    if (ev?.preferenceValue == "N") {
        emailUnverified = true
        def ua = ec.entity.find("moqui.security.UserAccount").condition("userId", ec.user.userId).one()
        if (ua?.username) ec.web.session.setAttribute("pendingVerifyEmail", ua.username)
    }
} finally { if (!adDis) ec.artifactExecution.enableAuthz() }

boolean alreadyDisabled = ec.artifactExecution.disableAuthz()
try {
    // IMPORTANT: no early `return` in this block. Moqui does NOT sync context
    // variables back across an early return in an inline <script>, so a `return`
    // here would silently drop orgValidationFailed and let the login through
    // (the D-1 gate-bypass bug). Use structured if/else so the script completes
    // normally and the flag reliably reaches the <if> below.
    if (ec.user.isInGroup("ADMIN")) {
        // Platform super-admins operate across tenants and are exempt from the
        // per-tenant org gate (matches the central module gate in ZenithApp).
        // Do NOT pin an active organization for a cross-tenant admin.
    } else {
        // Organization IDs are stored uppercase (= subdomain.toUpperCase()); idValue
        // is encrypted so matching is exact-ciphertext — try as typed, then uppercased,
        // so a user typing lower/mixed case is not wrongly rejected.
        def orgIdInput = organizationId?.trim()
        def orgIdList = ec.entity.find("mantle.party.PartyIdentification")
                .condition("partyIdTypeEnumId", "PtidOrgCode")
                .condition("idValue", orgIdInput).list()
        if (!orgIdList && orgIdInput) {
            orgIdList = ec.entity.find("mantle.party.PartyIdentification")
                .condition("partyIdTypeEnumId", "PtidOrgCode")
                .condition("idValue", orgIdInput.toUpperCase()).list()
        }
        if (!orgIdList) {
            // Generic (no org enumeration): don't reveal whether the org exists vs the
            // user simply isn't a member — same message as the not-a-member case below.
            orgValidationError = "That Organization ID is invalid, or your account doesn't have access to it."
            orgValidationFailed = true
        } else {
            def orgPartyId = orgIdList[0].partyId
            def userAcct = ec.entity.find("moqui.security.UserAccount")
                    .condition("userId", ec.user.userId).one()
            if (!userAcct?.partyId) {
                orgValidationError = "That Organization ID is invalid, or your account doesn't have access to it."
                orgValidationFailed = true
            } else {
                // ZE-ROLE-002: org membership is stored as PrtEmployee OR PrtAgent (and
                // future PrtMember) relationships to the org — not only PrtEmployee. The
                // narrow check wrongly rejected valid PrtAgent members with "Organization
                // ID is invalid". Match the same relationship types setup#UserOrganizationInfo does.
                def relList = ec.entity.find("mantle.party.PartyRelationship")
                        .condition("fromPartyId", userAcct.partyId)
                        .condition("toPartyId", orgPartyId)
                        .condition("relationshipTypeEnumId", "in", ["PrtEmployee", "PrtAgent", "PrtMember"])
                        .conditionDate("fromDate", "thruDate", ec.user.nowTimestamp).list()
                if (!relList) {
                    orgValidationError = "That Organization ID is invalid, or your account doesn't have access to it."
                    orgValidationFailed = true
                } else {
                    // Member of this org: bind the active organization.
                    ec.web.sessionAttributes.put("organizationPartyId", orgPartyId)
                    ec.user.setPreference("ACTIVE_ORGANIZATION", orgPartyId)
                }
            }
        }
    }
} finally {
    if (!alreadyDisabled) ec.artifactExecution.enableAuthz()
}

actions.script:
ec.artifactExecution.disableAuthz()
verifyOk = false
if (token) {
    def tp = ec.entity.find("moqui.security.UserPreference")
        .condition("preferenceKey", "EMAIL_VERIFY_TOKEN").condition("preferenceValue", token).disableAuthz().list()
    if (tp) {
        def uid = tp[0].userId
        ec.entity.makeValue("moqui.security.UserPreference")
            .setAll([userId:uid, preferenceKey:"EMAIL_VERIFIED", preferenceValue:"Y"]).createOrUpdate()
        def tv = ec.entity.find("moqui.security.UserPreference").condition("userId", uid)
            .condition("preferenceKey", "EMAIL_VERIFY_TOKEN").disableAuthz().one()
        if (tv != null) tv.delete()
        def ua = ec.entity.find("moqui.security.UserAccount").condition("userId", uid).disableAuthz().one()
        if (ua?.username) { ec.user.internalLoginUser(ua.username); ec.web.session.removeAttribute("pendingVerifyEmail") }
        verifyOk = true
    }
}
if (!verifyOk) ec.message.addError("This verification link is invalid or has already been used. Please sign in, or sign up again.")

ec.artifactExecution.disableAuthz()
def em = ec.web.session.getAttribute("pendingVerifyEmail")
if (em) {
    ec.service.sync().name("zenith.saas.SaasServices.send#SignupVerification")
        .parameters([email:em]).disableAuthz().call()
}
ec.message.addMessage("If your email still needs verifying, we've sent a fresh link. Please check your inbox and spam folder.")

ec.artifactExecution.disableAuthz()
try {
    def ga = ec.service.sync().name("zenith.saas.SaasServices.authenticate#GoogleUser")
        .parameter("idToken", credential).disableAuthz().call()
    if (ec.message.hasError()) {
        def em = ec.message.errorsString; ec.message.clearErrors()
        ec.web.sendJsonResponse([action:'error', error:em])
    } else {
        ec.web.sendJsonResponse([action:ga.action, redirectUrl:ga.redirectUrl])
    }
} catch (Exception e) {
    ec.message.clearErrors()
    ec.web.sendJsonResponse([action:'error', error:'Google sign-in failed. Please try again.'])
}

pre-actions.script:
// if user already logged in redirect to root
if (ec.user.userId) { sri.sendRedirectAndStopRender('/qapps/zenith/Dashboard'); return }

// Keep the idle tab on the sign-in screen. A subsequent visit can use the saved key.
def cookies = ec.web.request.cookies
if (cookies && ec.web.parameters.idle != 'Y') {
    def loginKeyCookie = cookies.find { it.name == 'moquiLoginKey' && it.value }
    if (loginKeyCookie) {
        boolean loggedIn = ec.user.loginUserKey(loginKeyCookie.value)
        if (loggedIn) {
            // A remembered key still needs the same verified-email and
            // active-organization membership gates as password login.
            boolean alreadyDisabled = ec.artifactExecution.disableAuthz()
            boolean allowed = true
            try {
                def unverified = ec.entity.find('moqui.security.UserPreference')
                        .condition('userId', ec.user.userId).condition('preferenceKey', 'EMAIL_VERIFIED').one()
                if (unverified?.preferenceValue == 'N') allowed = false
                if (!ec.user.isInGroup('ADMIN')) {
                    def orgId = ec.user.getPreference('ACTIVE_ORGANIZATION')
                    def partyId = ec.user.userAccount?.partyId
                    def member = orgId && orgId != '_NA_' && partyId && ec.entity.find('mantle.party.PartyRelationship')
                            .condition('fromPartyId', partyId).condition('toPartyId', orgId)
                            .condition('relationshipTypeEnumId', 'in', ['PrtEmployee', 'PrtAgent', 'PrtMember'])
                            .conditionDate('fromDate', 'thruDate', ec.user.nowTimestamp).count() > 0
                    if (member) ec.web.sessionAttributes.put('organizationPartyId', orgId)
                    else allowed = false
                }
            } finally { if (!alreadyDisabled) ec.artifactExecution.enableAuthz() }
            if (allowed) {
                sri.sendRedirectAndStopRender('/qapps/zenith/Dashboard')
                return
            }
            ec.user.logoutUser()
        }
        // Invalid, expired or no-longer-authorized key: clear it.
        def expCookie = new jakarta.servlet.http.Cookie("moquiLoginKey", "")
        expCookie.maxAge = 0
        expCookie.path = "/"
        expCookie.httpOnly = true
        expCookie.secure = ec.web.request.isSecure()
        ec.web.response.addCookie(expCookie)
    }
}

// jQuery/UI
html_scripts.add('/libs/jquery/jquery.min.js')
// Bootstrap
html_scripts.add('/libs/twitter-bootstrap/js/bootstrap.min.js')
// Moqui webroot layout
html_stylesheets.add('/css/webroot-layout.css')
// ZetaERP: /Login enhancements — double-submit guard (ZE-AUTH-008), password reveal (BUG-001)
// and the Continue-with-Google bootstrap. External so the JS isn't constrained by the inline
// onload attribute (no double-quotes / no '<'). /zenithstatic resolves on /Login unauthenticated.
html_scripts.add('/zenithstatic/js/login-enhance.js?v=1')
